    query_result = f"模拟搜索结果：关于'{query}'的相关信息..."
    search_msg = AIMessage(content=f"搜索完成: {query_result}")

    # 消息和结果都会被追加到现有列表后
    return {
        "messages": [search_msg],
        "search_results": [query_result]
    }

