def format_docs_with_sources(docs):
    formatted = []
    for i, doc in enumerate(docs):
        source = doc.metadata.get("source", "未知来源")
        formatted.append(f"[来源{i+1}: {source}]\n{doc.page_content}")
    return "\n\n---\n\n".join(formatted)

